@0 n="mean_soft_contact_coordination" d="Mean occupancy-weighted soft coordination normalized at the covalent-radius sum." B=997
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    amount = sum(1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= len(sites) or j >= len(sites) or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        oi = sites[i].get('occupancy')
        oj = sites[j].get('occupancy')
        oi = 1.0 if oi is None else max(0.0, oi)
        oj = 1.0 if oj is None else max(0.0, oj)
        total += oi * oj * max(0.0, 1.35 - d / (radii[i] + radii[j])) ** 2
    return float(total / (0.1225 * amount))
@end
@1 n="atomic_volume" d="Atomic volume in cubic angstroms." B=250
def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    return float(v) if v is not None and v > 0 else 0.0
@end
@2 n="atomic_charge_relaxation_scale" d="Neutral quadratic atomic charge-relaxation scale per atom." B=920
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    quadratic = 0.0
    linear = 0.0
    compliance = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        p = props.get(el) or {}
        ionization = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ionization is None or affinity is None or ionization <= 0:
            continue
        hardness = ionization - affinity
        if hardness <= 0:
            continue
        chi = 0.5 * (ionization + affinity)
        quadratic += x * chi * chi / hardness
        linear += x * chi / hardness
        compliance += x / hardness
        amount += x
    if compliance <= 0 or amount <= 0:
        return 0.0
    return float(max(0.0, 0.5 * (quadratic - linear * linear / compliance) / amount))
@end
@3 n="covalent_sphere_packing" d="Composition-averaged covalent-sphere volume divided by atomic volume." B=671
def feature(s):
    if not s:
        return 0.0
    v = s.get('volume_per_atom_A3')
    if v is None or v <= 0:
        v = (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3')
    if v is None or v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    amount = 0.0
    for el, x in (s.get('composition') or {}).items():
        if x is None or x <= 0:
            continue
        r = (props.get(el) or {}).get('covalent_radius_A')
        if r is None or r <= 0:
            continue
        total += x * r ** 3
        amount += x
    return float(4.1887902047863905 * total / (amount * v)) if amount > 0 else 0.0
@end
@4 n="compressed_contact_load" d="Occupancy-weighted squared compression below covalent-radius sums per atom." B=877
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        compression = max(0.0, 1.0 - d / (radii[i] + radii[j]))
        total += occ[i] * occ[j] * compression * compression
    return float(total / amount)
@end
@5 n="reduced_contact_distance_variance" d="Soft-contact-weighted variance of covalent-radius-normalized neighbor distances." B=1008
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [(props.get(a.get('element')) or {}).get('covalent_radius_A') or 0.0 for a in sites]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    first = 0.0
    second = 0.0
    weight = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or i < 0 or j < 0 or i >= n or j >= n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        reduced = d / (radii[i] + radii[j])
        w = occ[i] * occ[j] * max(0.0, 1.35 - reduced) ** 2
        first += w * reduced
        second += w * reduced * reduced
        weight += w
    if weight <= 0:
        return 0.0
    mean = first / weight
    return float(max(0.0, second / weight - mean * mean))
@end
